public class Main {
    public static void main(String[] args) {
        int a = 10;
        int b = 3;

        System.out.println("Tambah: " + (a + b));
        System.out.println("Bagi: " + (a / b)); // Pembagian integer akan membulatkan ke bawah!
        System.out.println("Modulo: " + (a % b)); // Sisa bagi 10 / 3 adalah 1
    }
}

